const NATIVE = '0x0000000000000000000000000000000000000000';

const RegistryPage = 'function page(uint256 start, uint256 n) view returns ((address launch, address token, address hook, address rewards, bytes32 poolId, uint8 mode, uint64 at, address registrar)[])';
const PoolForAccount = 'function poolForAccount(address account) view returns (bytes32)';
const PAGE = 200;
// Sale trades, emitted by each launch. `Bought.ethSpent` is net of the FLOOR Platform fee, which `TeamFeeCharged` reports
// just before it; `SoldBack.ethReturned` is the seller's gross share.
const Bought = 'event Bought(address indexed who, uint256 tokens, uint256 ethSpent, uint256 soldTotal, uint256 raisedTotal)';
const SoldBack = 'event SoldBack(address indexed who, uint256 tokens, uint256 ethReturned, uint256 soldTotal, uint256 raisedTotal)';
const TeamFeeCharged = 'event TeamFeeCharged(address indexed who, uint256 fee, bool sellBack)';
// The deployer's team buy emits only these (never Bought / SoldBack): its cost plus the FLOOR Platform fee it pays, and on a
// sell-back the cost, the deployer's gross share before the fee.
const TeamBought = 'event TeamBought(address indexed buyer, uint256 stepTokens, uint256 walletTokens, uint64 cliffs, uint256 cost, uint256 fee)';
const TeamBuySoldBack = 'event TeamBuySoldBack(address indexed buyer, uint256 tokens, uint256 cost, uint256 fee)';
// The hook's take on a pool trade, emitted by the chain's FLOOR hook per pool. `HookFee` is the whole take on the quote leg;
// `Skimmed`, `CreatorFee` (net of the referral share), `ReferralAccrued` and `HolderTax` are its parts, and the FLOOR
// Platform fee is the rest (it has no event of its own). `PlatformCut` is FLOOR's 2.5% of the skim, logged just before the
// `Skimmed` it was cut from (`PlatformCutDeferred` when it is held for a later sweep).
const HookFee = 'event HookFee(bytes32 indexed id, address indexed sender, uint128 feeAmount0, uint128 feeAmount1)';
const Skimmed = 'event Skimmed(bytes32 indexed poolId, uint256 ethAmount, uint256 skimBps)';
const CreatorFee = 'event CreatorFee(bytes32 indexed poolId, uint256 ethAmount, bool isBuy)';
const ReferralAccrued = 'event ReferralAccrued(bytes32 indexed poolId, address indexed referrer, address indexed asset, uint256 amount, uint256 grossCreatorFee)';
const HolderTax = 'event HolderTax(bytes32 indexed poolId, uint256 ethAmount, bool isBuy)';
const PlatformCut = 'event PlatformCut(bytes32 indexed poolId, uint256 amount)';
const PlatformCutDeferred = 'event PlatformCutDeferred(bytes32 indexed poolId, uint256 amount)';
// FLOOR's cut of what enters a pool's backing (`FloorPolicy.PLATFORM_BPS`).
const PLATFORM_BPS = 250n;
// Pool trades: the Uniswap v4 PoolManager's Swap, for FLOOR's pool ids only.
const Swap = 'event Swap(bytes32 indexed id, address indexed sender, int128 amount0, int128 amount1, uint160 sqrtPriceX96, uint128 liquidity, int24 tick, uint24 fee)';

const abs = (v: bigint) => (v < 0n ? -v : v);

// Robinhood Chain's native ETH is priced as its WETH; Arc's native USDC (18 decimals at the EVM level) as USDC.
const addQuote = (chain: string, balances: any, quote: string, amount: any, label: string) => {
  if (String(quote).toLowerCase() !== NATIVE) return balances.add(quote, amount, label);
  if (chain === 'robinhood') return balances.add('0x0Bd7D308f8E1639FAb988df18A8011f41EAcAD73', amount, label);
  if (chain === 'arc') return balances.addCGToken('usd-coin', Number(amount) / 1e18, label);
  balances.addGasToken(amount, label);
};

const fetch = async (options: FetchOptions) => {
  const { poolManager, quotes: listed } = chainConfig[options.chain];
  const dailyVolume = options.createBalances();
  const dailyFees = options.createBalances();
  const dailyRevenue = options.createBalances();
  const dailyProtocolRevenue = options.createBalances();
  const dailyHoldersRevenue = options.createBalances();
  const dailySupplySideRevenue = options.createBalances();
  const result = () => ({ dailyVolume, dailyFees, dailyUserFees: dailyFees, dailyRevenue, dailyProtocolRevenue, dailyHoldersRevenue, dailySupplySideRevenue });
  // One fee part, booked to the fees and to whoever it goes to.
  const book = (quote: string, amount: bigint, label: string, to: 'protocol' | 'holders' | 'supply') => {
    if (amount <= 0n) return;
    addQuote(options.chain, dailyFees, quote, amount, label);
    if (to === 'supply') addQuote(options.chain, dailySupplySideRevenue, quote, amount, label);
    else {
      addQuote(options.chain, dailyRevenue, quote, amount, label);
      addQuote(options.chain, to === 'protocol' ? dailyProtocolRevenue : dailyHoldersRevenue, quote, amount, label);
    }
  };

  const created: any[] = [];
  for (const registry of REGISTRIES) {
    // A registry not yet deployed at this block lists nothing (it answers no data).
    const count = Number(await options.api.call({ target: registry, abi: 'uint256:count', permitFailure: true }) ?? 0);
    for (let start = 0; start < count; start += PAGE)
      created.push(...await options.api.call({ target: registry, abi: RegistryPage, params: [start, Math.min(PAGE, count - start)] }));
  }
  if (!created.length) return result();

  // Only launches quoted in the native asset or a listed quote asset are counted.
  const createdQuotes: string[] = await options.api.multiCall({ abi: 'address:quoteToken', calls: created.map((l: any) => l.launch) });
  const allowed = new Set([NATIVE, ...listed.map((q) => q.toLowerCase())]);
  const kept = created.map((l: any, i: number) => ({ l, quote: createdQuotes[i] })).filter(({ quote }) => allowed.has(String(quote).toLowerCase()));
  if (!kept.length) return result();
  const launches = kept.map(({ l }) => l);
  const quotes: string[] = kept.map(({ quote }) => quote);

  const sales: string[] = launches.map((l: any) => l.launch.toLowerCase());
  const quoteOf = new Map(sales.map((s, i) => [s, quotes[i]]));

  // Sale phase: a buy's gross is its price plus the FLOOR Platform fee charged on it.
  const bought = await options.getLogs({ targets: sales, eventAbi: Bought, entireLog: true, parseLog: true });
  const soldBack = await options.getLogs({ targets: sales, eventAbi: SoldBack, entireLog: true, parseLog: true });
  const teamFees = await options.getLogs({ targets: sales, eventAbi: TeamFeeCharged, entireLog: true, parseLog: true });
  const teamBought = await options.getLogs({ targets: sales, eventAbi: TeamBought, entireLog: true, parseLog: true });
  const teamSoldBack = await options.getLogs({ targets: sales, eventAbi: TeamBuySoldBack, entireLog: true, parseLog: true });
  for (const l of bought) addQuote(options.chain, dailyVolume, quoteOf.get(l.address.toLowerCase())!, l.args.ethSpent, 'Sale buys');
  for (const l of teamFees) if (!l.args.sellBack) addQuote(options.chain, dailyVolume, quoteOf.get(l.address.toLowerCase())!, l.args.fee, 'Sale buys');
  for (const l of soldBack) addQuote(options.chain, dailyVolume, quoteOf.get(l.address.toLowerCase())!, l.args.ethReturned, 'Sale sell-backs');
  for (const l of teamBought) addQuote(options.chain, dailyVolume, quoteOf.get(l.address.toLowerCase())!, BigInt(l.args.cost) + BigInt(l.args.fee), 'Sale buys');
  for (const l of teamSoldBack) addQuote(options.chain, dailyVolume, quoteOf.get(l.address.toLowerCase())!, l.args.cost, 'Sale sell-backs');
  // The sale's one fee, the FLOOR Platform fee, on every buy and sell-back (the team buy's included).
  for (const l of teamFees) book(quoteOf.get(l.address.toLowerCase())!, BigInt(l.args.fee), 'FLOOR Platform fees', 'protocol');
  for (const l of teamBought) book(quoteOf.get(l.address.toLowerCase())!, BigInt(l.args.fee), 'FLOOR Platform fees', 'protocol');
  for (const l of teamSoldBack) book(quoteOf.get(l.address.toLowerCase())!, BigInt(l.args.fee), 'FLOOR Platform fees', 'protocol');

  // Pool phase: one side of each swap, the quote side. Currencies are sorted by address, so the quote is currency0 when its
  // address is the lower one (always for a native-quoted pool, whose currency0 is address(0)).
  // A launch's pool id is the hook's, bound at graduation (zero before).
  const poolIds: string[] = await options.api.multiCall({ abi: PoolForAccount, calls: launches.map((l: any) => ({ target: l.hook, params: [l.launch] })) });
  const pools = new Map<string, { quote: string; quoteIs0: boolean; hook: string }>();
  launches.forEach((l: any, i: number) => {
    const quote = quotes[i];
    pools.set(poolIds[i].toLowerCase(), { quote, quoteIs0: BigInt(quote) < BigInt(l.token), hook: l.hook.toLowerCase() });
  });
  // The PoolManager logs every v4 pool's swaps: ask only for FLOOR's, one pool id (the event's first indexed topic) at a time.
  const floorIds = [...pools.keys()].filter((id) => BigInt(id) !== 0n);
  const swaps = (await Promise.all(floorIds.map((id) => options.getLogs({ target: poolManager, eventAbi: Swap, extraTopics: [id], entireLog: true, parseLog: true })))).flat();

  // The hook's take, per FLOOR pool.
  const hooks = [...new Set(launches.map((l: any) => l.hook.toLowerCase()))];
  const ofPool = (l: any) => pools.get(String(l.args.id ?? l.args.poolId).toLowerCase());
  const [hookFees, skims, creators, referrals, holders, cuts, deferred] = await Promise.all(
    [HookFee, Skimmed, CreatorFee, ReferralAccrued, HolderTax, PlatformCut, PlatformCutDeferred].map((eventAbi) =>
      options.getLogs({ targets: hooks, eventAbi, entireLog: true, parseLog: true })),
  );

  // A buy's hook fee is taken before the swap from the quote the trader paid (`beforeSwap`, logged just before the
  // PoolManager's Swap): the trade's size is the Swap's quote leg plus it.
  const feesByTx = new Map<string, any[]>();
  for (const f of hookFees) {
    const k = `${String(f.transactionHash).toLowerCase()}:${String(f.args.id).toLowerCase()}`;
    feesByTx.set(k, [...(feesByTx.get(k) ?? []), f]);
  }
  for (const s of swaps) {
    const id = String(s.args.id).toLowerCase();
    const pool = pools.get(id);
    // A swap the hook sends itself (its `_nudge` at a ratchet) is the protocol's own action, not a trade.
    if (!pool || String(s.args.sender).toLowerCase() === pool.hook) continue;
    const quoteSigned = BigInt(pool.quoteIs0 ? s.args.amount0 : s.args.amount1);
    const quoteLeg = abs(quoteSigned);
    const quoteIn = quoteSigned < 0n;
    let hookFee = 0n;
    if (quoteIn) {
      const before = (feesByTx.get(`${String(s.transactionHash).toLowerCase()}:${id}`) ?? [])
        .filter((f) => Number(f.logIndex) < Number(s.logIndex))
        .sort((a, b) => Number(b.logIndex) - Number(a.logIndex))[0];
      if (before) hookFee = BigInt(before.args.feeAmount0) + BigInt(before.args.feeAmount1);
    }
    addQuote(options.chain, dailyVolume, pool.quote, quoteLeg + hookFee, 'Pool swaps');
    // The LP fee (Swap.fee pips) is charged on the input: the quote on a buy, exact; on a sell the token, stated here in
    // the quote at the swap's own rate. Every position in a FLOOR pool is FLOOR's own (the protocol-owned liquidity, the
    // bid, the cushion, the steps), so the LP fee goes into the pool's backing. FLOOR's 2.5% of it is the PlatformCut
    // logged when it is swept in (booked below), so the backing's share here is the other 97.5%.
    const fee = BigInt(s.args.fee);
    const lp = quoteIn ? (quoteLeg * fee) / 1_000_000n : (quoteLeg * fee) / (1_000_000n - fee);
    book(pool.quote, lp - (lp * PLATFORM_BPS) / 10_000n, 'LP fees: backing', 'holders');
  }

  const total = new Map<string, bigint>();
  const add = (pool: string, v: bigint) => total.set(pool, (total.get(pool) ?? 0n) + v);
  for (const l of hookFees) {
    const pool = ofPool(l);
    if (!pool) continue;
    add(String(l.args.id).toLowerCase(), BigInt(l.args.feeAmount0) + BigInt(l.args.feeAmount1));
  }
  // FLOOR's cut of a skim: the PlatformCut / PlatformCutDeferred of the same pool in the same transaction, just before it.
  const cutsByTx = new Map<string, any[]>();
  for (const c of [...cuts, ...deferred]) {
    const k = String(c.transactionHash).toLowerCase();
    cutsByTx.set(k, [...(cutsByTx.get(k) ?? []), c]);
  }
  const paired = new Set<any>();
  for (const l of skims) {
    const pool = ofPool(l);
    if (!pool) continue;
    const id = String(l.args.poolId).toLowerCase();
    const skim = BigInt(l.args.ethAmount);
    const before = (cutsByTx.get(String(l.transactionHash).toLowerCase()) ?? [])
      .filter((c) => String(c.args.poolId).toLowerCase() === id && Number(c.logIndex) < Number(l.logIndex))
      .sort((a, b) => Number(b.logIndex) - Number(a.logIndex))[0];
    if (before) paired.add(before);
    const cut = before ? BigInt(before.args.amount) : 0n;
    book(pool.quote, cut, 'Floor skim: FLOOR\'s cut', 'protocol');
    book(pool.quote, skim - cut, 'Floor skim: backing', 'holders');
    add(id, -skim);
  }
  // FLOOR's 2.5% of everything else that enters a pool's backing: the raise at graduation, the staircase's sales and the
  // swept LP fees. Each is a PlatformCut (or PlatformCutDeferred) of its own.
  for (const c of [...cuts, ...deferred]) {
    if (paired.has(c)) continue;
    const pool = ofPool(c);
    if (pool) book(pool.quote, BigInt(c.args.amount), 'FLOOR\'s cut of the backing', 'protocol');
  }
  for (const l of creators) {
    const pool = ofPool(l);
    if (!pool) continue;
    book(pool.quote, BigInt(l.args.ethAmount), 'Creator fees', 'supply');
    add(String(l.args.poolId).toLowerCase(), -BigInt(l.args.ethAmount));
  }
  for (const l of referrals) {
    const pool = ofPool(l);
    if (!pool) continue;
    book(pool.quote, BigInt(l.args.amount), 'Referral fees', 'supply');
    add(String(l.args.poolId).toLowerCase(), -BigInt(l.args.amount));
  }
  for (const l of holders) {
    const pool = ofPool(l);
    if (!pool) continue;
    book(pool.quote, BigInt(l.args.ethAmount), 'Holder fees', 'holders');
    add(String(l.args.poolId).toLowerCase(), -BigInt(l.args.ethAmount));
  }
  // What is left of the hook's take is the FLOOR Platform fee.
  for (const [id, rest] of total) book(pools.get(id)!.quote, rest, 'FLOOR Platform fees', 'protocol');

  return result();
};

const adapter: SimpleAdapter = {
  version: 2,
  pullHourly: true,
  fetch,
  adapter: chainConfig,
  // Graduated pools are Uniswap v4 pools, so their swaps are also in Uniswap v4's volume.
  doublecounted: true,
  methodology: {
    Fees: "Every fee a FLOOR launch's traders pay: on the sale, the FLOOR Platform fee; on the pool, the hook's skim, creator fee (with its referral share), holder fee and FLOOR Platform fee, read from the hook's HookFee / Skimmed / CreatorFee / ReferralAccrued / HolderTax events, and the Uniswap v4 LP fee; and FLOOR's 2.5% cut of everything that enters a pool's backing (the raise at graduation, the staircase's sales, the swept LP fees), from PlatformCut.",
    UserFees: "The same as Fees: every fee is paid by the trader.",
    Revenue: "The FLOOR Platform fee, FLOOR's cuts, the skim, the holder fee and the LP fee (every position in a FLOOR pool is FLOOR's own).",
    ProtocolRevenue: "The FLOOR Platform fee, and FLOOR's 2.5% cut of everything that enters a pool's backing: the skim, the raise at graduation, the staircase's sales and the LP fee.",
    HoldersRevenue: "The holder fee, and the rest of the skim and of the LP fee, which go into the pool's backing (the floor under every holder's tokens).",
    SupplySideRevenue: "The creator fee and its referral share.",
    Volume: "Every trade on a FLOOR launch quoted in the chain's native asset or a quote asset FLOOR lists, in that asset: buys (with the FLOOR Platform fee) and sell-backs on each launch's sale, read from its Bought / TeamFeeCharged / SoldBack events and the deployer's TeamBought / TeamBuySoldBack, then every Uniswap v4 Swap on a graduated launch's pool: its quote side, plus on a buy the hook fee taken from the quote before the swap.",
  },
  breakdownMethodology: {
    Fees: {
      'FLOOR Platform fees': 'TeamFeeCharged.fee and the team buy\'s fee on the sale; on the pool, HookFee less the parts the hook logs.',
      'Floor skim: backing': 'Skimmed.ethAmount less FLOOR\'s cut.',
      'Floor skim: FLOOR\'s cut': 'The PlatformCut (or PlatformCutDeferred) logged with each Skimmed: 2.5% of the skim.',
      'Creator fees': 'CreatorFee.ethAmount, net of the referral share.',
      'Referral fees': 'ReferralAccrued.amount, 10% of the gross creator fee.',
      'Holder fees': 'HolderTax.ethAmount.',
      'FLOOR\'s cut of the backing': 'Every other PlatformCut / PlatformCutDeferred: 2.5% of the raise at graduation, of the staircase\'s sales and of the swept LP fees as they enter the backing.',
      'LP fees: backing': 'Swap.fee pips of the input (on a sell, stated in the quote at the swap\'s rate), less FLOOR\'s 2.5%: the LP fee of FLOOR\'s own positions, which goes into the pool\'s backing.',
    },
    Volume: {
      'Sale buys': 'Bought.ethSpent plus the FLOOR Platform fee TeamFeeCharged reports for the buy, and the team buy\'s TeamBought.cost + fee.',
      'Sale sell-backs': 'SoldBack.ethReturned, the seller\'s gross share before the fee, and the team buy\'s TeamBuySoldBack.cost.',
      'Pool swaps': 'The absolute quote-side amount of each PoolManager Swap whose pool id is a FLOOR launch\'s, plus on a buy the HookFee logged just before it.',
    },
  },
};

export default adapter;
